// Enum de status de envio dos arquivos.
var PoUploadStatus;
(function (PoUploadStatus) {
    // Enviou com sucesso.
    PoUploadStatus[PoUploadStatus["Uploaded"] = 0] = "Uploaded";
    // Está enviando.
    PoUploadStatus[PoUploadStatus["Uploading"] = 1] = "Uploading";
    // Ocorreu algum erro no envio.
    PoUploadStatus[PoUploadStatus["Error"] = 2] = "Error";
    // Não enviou ou aconteceu algum erro.
    PoUploadStatus[PoUploadStatus["None"] = 3] = "None";
})(PoUploadStatus || (PoUploadStatus = {}));

// Classe responsável pelo arquivo do PO Upload
class PoUploadFile {
    // Nome do arquivo.
    name;
    // Arquivo bruto.
    rawFile;
    // Status de envio do arquivo.
    status;
    // Identificador do arquivo.
    uid;
    // Extensão do arquivo.
    extension;
    // Tamanho do arquivo em bytes;
    size;
    // propriedade para auxiliar a exibição do texto no componente progress
    displayName;
    // porcentagem utilizada para repassar ao componente progress
    percent;
    // indica que o tamanho do arquivo não é permitido
    sizeNotAllowed;
    // indica que a extensão do arquivo não é permitida
    extensionNotAllowed;
    // Propriedade interna que indica que o status de sucesso deve estar oculto
    hideDoneContent;
    // Propriedade interna para mensagem de erro
    errorMessage;
    // Propriedade interna para url da thumbnail
    thumbnailUrl;
    // Propriedade interna para controlar se houve erro ao carregar a imagem da thumbnail.
    imageError;
    constructor(file) {
        if (file) {
            this.name = file.name;
            this.displayName = `${file.name} - ${this.getFileSize(file.size)}`;
            this.extension = this.getExtension(file.name);
            this.size = file.size;
            this.rawFile = file;
            this.uid = this.generateUUID();
            this.status = PoUploadStatus.None;
        }
    }
    getExtension(value) {
        if (value) {
            const extension = value.substr(value.lastIndexOf('.'));
            return extension.toLowerCase();
        }
        return '';
    }
    generateUUID() {
        function s4() {
            return Math.floor((1 + Math.random()) * 0x10000)
                .toString(16)
                .substring(1);
        }
        return s4() + s4() + '-' + s4() + '-' + s4() + '-' + s4() + '-' + s4() + s4() + s4();
    }
    // Retorna o tamanho do arquivo em KBytes.
    getFileSize(size) {
        let kbSize = 0;
        if (size) {
            kbSize = Math.ceil(size / 1024);
        }
        return `${kbSize} KB`;
    }
}

